-- MIGRATION STEP 2 (FULL): Update content_services_meta with 37 descriptions
-- Run this AFTER Step 1. Should return "1 row affected".

UPDATE content_services_meta
SET meta = jsonb_set(
  jsonb_set(
    meta,
    '{tips}',
    '[{"packageId":"prime-essential-exterior","chemicalIds":["a1000005-0000-0000-0000-000000000005","a1000010-0000-0000-0000-000000000010","a1000012-0000-0000-0000-000000000012","a1000016-0000-0000-0000-000000000016","a1000030-0000-0000-0000-000000000030","a1000031-0000-0000-0000-000000000031","a1000029-0000-0000-0000-000000000029"],"notes":"Essential Exterior Guide:\n- Inspect for heavy mud/bugs; pre-treat these areas.\n- Foam dwell time 3-5 mins; do not let dry.\n- Top-down wash with grit guards.\n- Hand dry with plush microfiber."},{"packageId":"prime-essential-interior","chemicalIds":["a1000004-0000-0000-0000-000000000004","a1000006-0000-0000-0000-000000000006","a1000013-0000-0000-0000-000000000013","a1000025-0000-0000-0000-000000000025","a1000033-0000-0000-0000-000000000033"],"notes":"Essential Interior Guide:\n- Remove all trash and loose items first.\n- Vacuum in sections.\n- Wipe dash/console with safe cleaner.\n- Glass cleaning is the final touch."},{"packageId":"prime-essential-full","chemicalIds":["a1000004-0000-0000-0000-000000000004","a1000006-0000-0000-0000-000000000006","a1000013-0000-0000-0000-000000000013","a1000025-0000-0000-0000-000000000025","a1000033-0000-0000-0000-000000000033","a1000005-0000-0000-0000-000000000005","a1000010-0000-0000-0000-000000000010","a1000012-0000-0000-0000-000000000012","a1000016-0000-0000-0000-000000000016","a1000030-0000-0000-0000-000000000030","a1000031-0000-0000-0000-000000000031","a1000029-0000-0000-0000-000000000029"],"notes":"Full Detail Guide:\n- Balance time between inside and out.\n- Wash exterior first while interior dries.\n- Wipe door jambs last."}]'::jsonb
  ),
  '{descriptions}',
  '[
    {"id":"a1000001-0000-0000-0000-000000000001","purpose":"Removes below-surface paint defects including swirl marks, light to moderate scratches, water spots, and oxidation. Simultaneously finishes to a high-gloss shine ready for wax, sealant, or ceramic coating. A true all-in-one paint correction solution.","instructions":"1. Shake well before use. No dilution required — product is ready to use.\n2. Work in a shaded area out of direct sunlight.\n3. Apply 4 to 5 dime-size drops directly onto chosen pad.\n4. Work a 2x2 foot section at a time using slow back-and-forth overlapping motions.\n5. For scratch removal: use a rotary or DA polisher with a wool or foam cutting pad.\n6. For finishing: switch to a soft foam finishing pad on a DA polisher.\n7. Buff until product works in.\n8. Wipe off residue immediately.\n9. Follow with a wax or coating.","dilutions":[{"scenario":"Standard","ratio":"RTU"},{"scenario":"Scratch Removal","ratio":"RTU (use cutting pad)"},{"scenario":"Finishing/Polish","ratio":"RTU (use finishing pad)"}]},
    {"id":"a1000002-0000-0000-0000-000000000002","purpose":"All-surface interior and exterior cleaning degreaser. Use on carpets, cloth seats, vinyl, leather, headliners, door jambs, engine bays, wheel wells, tires, exterior trim, and bumper covers. Can also be used to strip wax from paint.","instructions":"1. Dilute product according to the job scenario below.\n2. Test on a small inconspicuous area first.\n3. Apply diluted product via spray bottle or applicator.\n4. If necessary, agitate with a soft brush or microfiber towel.\n5. Allow to dwell for 30 to 45 seconds on stubborn stains.\n6. Rinse thoroughly with clean water or wipe clean.\n7. Do not allow product to dry on the surface.","dilutions":[{"scenario":"Maintenance / Light","ratio":"20:1"},{"scenario":"Standard","ratio":"10:1"},{"scenario":"Heavy Dirt / Degreasing","ratio":"4:1"}]},
    {"id":"a1000003-0000-0000-0000-000000000003","purpose":"Tire and exterior trim dressing. Enhances the appearance of tires with a deep, rich black shine. Conditions and protects rubber from UV damage and cracking. Also suitable for plastic trim, bumpers, and fender liners.","instructions":"1. Dilute product per the scenario below before application.\n2. Ensure the tire or trim surface is clean.\n3. Apply diluted product to a foam tire applicator or microfiber towel.\n4. Work into the surface using circular or back-and-forth motions.\n5. Allow product to penetrate for 1 to 2 minutes.\n6. For tires: allow to dry or buff lightly.\n7. For trim: wipe off any excess to prevent drips.\n8. Allow to fully cure before driving.","dilutions":[{"scenario":"Maintenance / Light","ratio":"4:1"},{"scenario":"Standard","ratio":"2:1"},{"scenario":"Heavy Dirt / Degreasing","ratio":"1:1 (RTU)"}]},
    {"id":"a1000004-0000-0000-0000-000000000004","purpose":"General interior cleaning on dashboards, door panels, consoles, vinyl seats, plastic trim, and rubber surfaces. Ideal for maintenance cleaning between deeper detail sessions.","instructions":"1. Shake well before use.\n2. Spray directly onto the surface or onto a clean microfiber towel.\n3. Wipe surface with the towel using even back-and-forth or circular motions.\n4. For stubborn stains, allow to dwell for 15 to 30 seconds then agitate with a soft brush.\n5. Wipe clean with a fresh dry microfiber towel.\n6. No rinsing required.","dilutions":[{"scenario":"Maintenance / Light","ratio":"RTU"},{"scenario":"Standard","ratio":"RTU"},{"scenario":"Heavy Dirt / Degreasing","ratio":"RTU"}]},
    {"id":"a1000005-0000-0000-0000-000000000005","purpose":"Wheel and tire cleaning. Removes brake dust, road tar, iron deposits, and embedded grime from wheels of all types. Prepares tire surface for dressing application.","instructions":"1. Rinse wheels and tires with water to remove loose dirt before applying.\n2. Apply product directly to the wheel and tire surface.\n3. Allow to dwell for 1 to 3 minutes.\n4. Agitate with a wheel brush, lug nut brush, or wheel woolie to reach all areas.\n5. Rinse thoroughly with a strong stream of water.\n6. Dry with a dedicated wheel towel.\n7. Follow with tire dressing if desired.","dilutions":[{"scenario":"Maintenance / Light","ratio":"RTU"},{"scenario":"Standard","ratio":"RTU"},{"scenario":"Heavy Dirt / Degreasing","ratio":"RTU"}]},
    {"id":"a1000006-0000-0000-0000-000000000006","purpose":"Deep cleaning of carpets, cloth seats, and upholstery. Removes grease, oil, food stains, dirt, and pet-related soiling. Also suitable for vinyl surfaces, engine bays, and wheel wells at stronger dilutions. Step 2 in P&S Double Black system.","instructions":"1. Vacuum and dry-brush carpets and upholstery thoroughly.\n2. Dilute Carpet Bomber according to scenario.\n3. Apply a light mist of diluted product to the area.\n4. Allow to penetrate and dwell for a minimum of 3 minutes.\n5. Agitate with a carpet brush using circular scrubbing motions.\n6. Extract with a wet/dry vacuum or carpet extractor.\n7. Allow surface to dry completely.\n8. For Step 2 use: apply after Terminator.","dilutions":[{"scenario":"Maintenance / Light","ratio":"8:1"},{"scenario":"Standard","ratio":"7:1"},{"scenario":"Heavy Dirt / Degreasing","ratio":"5:1"}]},
    {"id":"a1000007-0000-0000-0000-000000000007","purpose":"Long-term paint protection and enhancement. Creates a hard ceramic barrier that repels water and contaminants, enhances gloss and color depth, protects against UV fading, and significantly reduces the effort required to maintain a clean vehicle.","instructions":"1. Thoroughly wash and clay-bar the vehicle.\n2. Correct any paint defects before application.\n3. Perform an IPA wipe-down on all panels.\n4. Shake the Cerakote bottle for 30 seconds.\n5. Work panel by panel — apply a few drops to applicator suede.\n6. Apply in straight overlapping lines using light pressure.\n7. Within 1 to 5 minutes the coating will flash and bead up.\n8. Buff off with a clean microfiber towel immediately upon flash.\n9. Inspect panel under a light source.\n10. Allow vehicle to cure for 2 hours. Do not wash for 24 hours.","dilutions":[{"scenario":"Standard","ratio":"RTU"},{"scenario":"Full Vehicle Coating","ratio":"RTU"}]},
    {"id":"a1000008-0000-0000-0000-000000000008","purpose":"Color enhancement and protection specifically for black and dark-colored vehicles. Removes light swirl marks and surface hazing. Delivers deep, rich black color depth and long-lasting ceramic protection.","instructions":"1. Wash and dry the vehicle thoroughly.\n2. Apply to cool paint in a shaded area.\n3. Apply a small amount of product to a foam applicator pad.\n4. Work into the paint in straight overlapping motions — one panel at a time.\n5. Allow to haze — approximately 3 to 5 minutes.\n6. Buff off the haze using a clean, dry microfiber towel.\n7. Flip the towel and perform a final wipe.\n8. For deeper results, apply a second coat after the first cures.","dilutions":[{"scenario":"Standard","ratio":"RTU"},{"scenario":"Second Coat Application","ratio":"RTU"}]},
    {"id":"a1000009-0000-0000-0000-000000000009","purpose":"All-in-one interior cleaning, conditioning, and protection. Removes dirt, fingerprints, stains, and odors. Protects leather and vinyl from UV cracking and fading. Reduces dust re-attraction.","instructions":"1. Shake well before use.\n2. Spray directly onto the surface or onto a clean microfiber towel.\n3. Wipe the surface evenly to clean and apply the conditioner.\n4. For stubborn stains, allow to dwell for 30 seconds.\n5. For deeper protection: apply a second coat immediately and wipe again.\n6. Flip towel to a clean side and wipe away excess.\n7. Allow to dry naturally.\n8. Safe for use on touch screens.","dilutions":[{"scenario":"Standard","ratio":"RTU"},{"scenario":"Deep Conditioning","ratio":"RTU (apply second coat)"}]},
    {"id":"a1000010-0000-0000-0000-000000000010","purpose":"Pre-wash foam cannon application or traditional bucket car wash shampoo. Safely removes surface dirt, dust, road grime, and light contaminants. Preserves existing wax and sealant protection.","instructions":"1. Dilute per the scenario below in a foam cannon or wash bucket.\n2. Apply to the vehicle starting from the top.\n3. Allow foam to dwell for 1 to 2 minutes.\n4. For foam cannon: rinse off without contact wash for a pre-wash.\n5. For bucket wash: use a clean wash mitt to gently agitate.\n6. Rinse thoroughly from top to bottom with clean water.\n7. Dry immediately with a soft microfiber drying towel.","dilutions":[{"scenario":"Maintenance / Light","ratio":"10:1"},{"scenario":"Standard","ratio":"6:1"},{"scenario":"Heavy Dirt / Degreasing","ratio":"4:1"}]},
    {"id":"a1000011-0000-0000-0000-000000000011","purpose":"Multi-surface dressing and protectant for interior and exterior use. Enhances the appearance of plastic, rubber, vinyl, and tire surfaces. Provides UV protection and a uniform sheen.","instructions":"1. Ensure all surfaces are clean and free of dirt.\n2. Spray directly onto the surface or onto a foam applicator.\n3. Spread evenly using a foam applicator or microfiber towel.\n4. Buff lightly to achieve desired sheen level.\n5. Wipe off any excess with a clean microfiber towel.\n6. For tires: allow to fully dry before driving to prevent sling.","dilutions":[{"scenario":"Maintenance / Light","ratio":"RTU"},{"scenario":"Standard","ratio":"RTU"},{"scenario":"Heavy Dirt / Degreasing","ratio":"RTU"}]},
    {"id":"a1000012-0000-0000-0000-000000000012","purpose":"Professional wheel cleaning and brake dust removal. Dissolves ferrous contamination (brake dust, iron fallout) and road tar on contact. Prepares wheels for dressing or coating application.","instructions":"1. Rinse wheel and tire with water to remove loose dirt.\n2. Dilute Dark Fury per the job scenario.\n3. Spray diluted product liberally onto the cool wheel.\n4. Allow to dwell for 2 to 5 minutes — product will visually change color.\n5. Agitate with a wheel brush, lug nut brush, and wheel woolie.\n6. Rinse thoroughly with a strong stream of water.\n7. Follow with a tire dressing and wheel sealant if desired.\n8. Do not allow product to dry on the wheel.","dilutions":[{"scenario":"Maintenance / Light","ratio":"10:1"},{"scenario":"Standard","ratio":"7:1"},{"scenario":"Heavy Dirt / Degreasing","ratio":"4:1"}]},
    {"id":"a1000013-0000-0000-0000-000000000013","purpose":"Interior plastic and vinyl cleaning. Removes embedded dirt, grease, finger oils, and grime from dashboard plastics, door panels, center consoles, and vinyl surfaces. Ideal pre-treatment.","instructions":"1. Dilute product per the job scenario.\n2. Spray diluted product onto the surface or onto a clean microfiber towel.\n3. Wipe surface evenly with a microfiber towel or soft detailing brush.\n4. For textured plastic: agitate with a soft detailing brush.\n5. Wipe clean with a fresh dry microfiber towel.\n6. Follow with an interior dressing or protectant.","dilutions":[{"scenario":"Maintenance / Light","ratio":"10:1"},{"scenario":"Standard","ratio":"10:1"},{"scenario":"Heavy Dirt / Degreasing","ratio":"4:1"}]},
    {"id":"a1000014-0000-0000-0000-000000000014","purpose":"Enzyme-based cleaning and permanent odor elimination for carpets, seats, and upholstery. Breaks down organic stains biologically. Eliminates pet odors, smoke, food odors, and protein-based stains at the source.","instructions":"1. Vacuum and pre-treat the area before applying.\n2. Apply product directly to the stained or odor-affected area.\n3. Allow product to dwell for 5 to 10 minutes.\n4. Agitate with a brush or microfiber towel.\n5. Extract with a wet/dry vac or blot clean.\n6. Allow surface to dry completely. Enzymes continue working as the area dries.\n7. Repeat application for severe stains or odors.","dilutions":[{"scenario":"Maintenance / Light","ratio":"RTU"},{"scenario":"Standard","ratio":"RTU"},{"scenario":"Heavy Dirt / Degreasing","ratio":"RTU (multiple passes)"}]},
    {"id":"a1000015-0000-0000-0000-000000000015","purpose":"Quick detailing spray for maintenance between full washes. Removes light contamination, fingerprints, and water spots. Adds a layer of gloss and paint protection. Safe as a clay bar lubricant.","instructions":"1. Shake well before use.\n2. Lightly mist the product onto a clean microfiber towel or directly onto the panel.\n3. Gently wipe the surface using light, overlapping strokes.\n4. Flip towel to a clean dry side and perform a final buff.\n5. Work one panel at a time.\n6. Do not use on heavily soiled surfaces.\n7. Safe to use on warm surfaces.","dilutions":[{"scenario":"Standard","ratio":"RTU"},{"scenario":"Clay Bar Lubricant","ratio":"RTU (mist lightly ahead of clay)"}]},
    {"id":"a1000016-0000-0000-0000-000000000016","purpose":"Post-wash drying aid and polymer sealant. Applied to wet paint after the final rinse to prevent hard water spotting. Enhances gloss and adds a layer of paint protection with every wash.","instructions":"1. Apply immediately after the final rinse while vehicle is still wet.\n2. Dilute per the scenario in a spray bottle.\n3. Spray liberally over wet panels — one section at a time.\n4. Use a clean microfiber drying towel to dry the panel immediately.\n5. Flip to a dry side of the towel and perform a final buff.\n6. Work quickly on each panel before moving to the next.\n7. Product is effective even in direct sunlight.","dilutions":[{"scenario":"Maintenance / Light","ratio":"20:1"},{"scenario":"Standard","ratio":"20:1"},{"scenario":"Heavy Dirt / Degreasing","ratio":"20:1"}]},
    {"id":"a1000017-0000-0000-0000-000000000017","purpose":"Premium maintenance car wash that cleans and conditions paint simultaneously. Removes road grime, bird droppings, and surface contaminants while enhancing gloss and preserving existing protection.","instructions":"1. Dilute product per the job scenario.\n2. Rinse the vehicle thoroughly with water to remove loose dirt.\n3. Fill wash bucket with diluted solution and generate foam.\n4. For foam cannon: dilute at 5:1 and apply foam to vehicle.\n5. Wash from top downward using a clean microfiber wash mitt.\n6. Rinse mitt frequently using the two-bucket method.\n7. Rinse the vehicle thoroughly from top to bottom.\n8. Dry immediately with a soft microfiber drying towel.","dilutions":[{"scenario":"Maintenance / Light","ratio":"5:1"},{"scenario":"Standard","ratio":"5:1"},{"scenario":"Foam Cannon","ratio":"5:1"}]},
    {"id":"a1000018-0000-0000-0000-000000000018","purpose":"Eco-friendly all-purpose cleaner for interior and exterior use. Removes grease, dirt, and grime from a wide variety of automotive surfaces. A responsible choice minimizing environmental impact.","instructions":"1. Dilute product to the appropriate concentration.\n2. Apply to the target surface via spray bottle or applicator.\n3. Agitate with a microfiber towel or soft brush as needed.\n4. Wipe clean or rinse thoroughly with water.\n5. Safe for use in enclosed spaces — low VOC formula.","dilutions":[{"scenario":"Maintenance / Light","ratio":"10:1"},{"scenario":"Standard","ratio":"6:1"},{"scenario":"Heavy Dirt / Degreasing","ratio":"3:1"}]},
    {"id":"a1000019-0000-0000-0000-000000000019","purpose":"Interior cleaning and long-term surface protection. Removes dust, fingerprints, and light stains. Applies a ceramic protective layer on all interior surfaces that repels contaminants and UV rays.","instructions":"1. Shake well before use.\n2. Spray directly onto the surface or onto a clean microfiber towel.\n3. Wipe evenly across the surface using light, overlapping motions.\n4. Allow product to bond to the surface for 1 to 2 minutes.\n5. Buff off with a clean dry microfiber towel.\n6. For leather: apply to a towel first rather than spraying directly.","dilutions":[{"scenario":"Standard","ratio":"RTU"},{"scenario":"Deep Treatment","ratio":"RTU (apply second coat)"}]},
    {"id":"a1000020-0000-0000-0000-000000000020","purpose":"Professional-grade automotive glass cleaning on windshields, side windows, rear glass, mirrors. Removes interior film, fingerprints, haze, bugs, and road contamination from glass surfaces.","instructions":"1. Product is ready to use — no dilution required.\n2. For interior glass: spray product onto a clean microfiber glass towel.\n3. For exterior glass: spray directly onto the glass surface.\n4. Wipe in straight overlapping motions.\n5. Immediately follow with a second dry microfiber towel to buff.\n6. For heavily soiled glass: apply a second pass.\n7. Do not use on surfaces other than glass.","dilutions":[{"scenario":"Standard","ratio":"RTU"},{"scenario":"Heavily Soiled Glass","ratio":"RTU (double pass)"}]},
    {"id":"a1000021-0000-0000-0000-000000000021","purpose":"Professional leather surface cleaning on automotive seats, door panels, steering wheels, and trim. Removes embedded dirt, body oils, sweat, and surface contamination. Prepares leather for conditioning.","instructions":"1. Dilute product per the job scenario.\n2. Apply diluted product to a soft horsehair leather brush or microfiber applicator.\n3. Work into the leather surface in circular motions using a light touch.\n4. Agitate gently to lift dirt from the pores and grain.\n5. Wipe away loosened dirt and product residue with a clean towel.\n6. Repeat for heavily soiled areas.\n7. Allow the leather to dry slightly before applying conditioner.\n8. Always follow with a quality leather conditioner.","dilutions":[{"scenario":"Maintenance / Light","ratio":"6:1"},{"scenario":"Standard","ratio":"4:1"},{"scenario":"Heavy Dirt / Degreasing","ratio":"2:1"}]},
    {"id":"a1000022-0000-0000-0000-000000000022","purpose":"Deep conditioning and protection of automotive leather surfaces after cleaning. Restores natural leather softness and flexibility. Prevents premature cracking, fading, and drying.","instructions":"1. Apply only after leather has been cleaned with a dedicated cleaner.\n2. Apply a small amount of conditioner to a foam applicator or towel.\n3. Spread evenly across the leather surface in circular motions.\n4. Allow conditioner to penetrate for 3 to 5 minutes.\n5. Buff off any excess with a clean, dry microfiber towel.\n6. Do not over-apply — less is more with leather conditioner.\n7. Allow leather to fully absorb the conditioner before use.","dilutions":[{"scenario":"Standard","ratio":"RTU"},{"scenario":"Dry / Cracked Leather","ratio":"RTU (apply second coat)"}]},
    {"id":"a1000023-0000-0000-0000-000000000023","purpose":"Heavy-duty engine bay degreasing, wheel well cleaning, and pre-wash exterior degreasing. Removes petroleum deposits, oil spills, road tar, and heavy built-up grime.","instructions":"1. Dilute per the job scenario below before use.\n2. Apply to a cool or warm engine — never a very hot engine.\n3. Spray diluted product liberally onto the target area.\n4. Allow to dwell for 3 to 5 minutes for heavy grease.\n5. Agitate with a stiff brush on heavily soiled areas.\n6. Rinse thoroughly with a strong stream of water.\n7. Protect sensitive electrical components before rinsing.","dilutions":[{"scenario":"Maintenance / Light","ratio":"20:1"},{"scenario":"Standard","ratio":"10:1"},{"scenario":"Heavy Dirt / Degreasing","ratio":"4:1"}]},
    {"id":"a1000024-0000-0000-0000-000000000024","purpose":"Multi-use rinseless car wash, waterless wash, clay lubricant, quick detailer, and interior cleaner. Perfect for apartment dwellers, mobile detailers, and winter washing.","instructions":"1. For Rinseless Wash: Add 1 oz to 2 gallons of water. Wash one section at a time. Dry immediately. No rinsing required.\n2. For Quick Detailer / Drying Aid: Dilute 8 oz per 1 gallon (16:1).\n3. For Clay Lubricant: Dilute 2 oz per 1 gallon (64:1).\n4. For Interior Cleaning: Dilute 6 oz per 1 gallon.","dilutions":[{"scenario":"Rinseless / Waterless Wash","ratio":"256:1 (1 oz per 2 gal)"},{"scenario":"Quick Detailer","ratio":"16:1"},{"scenario":"Clay Lubricant","ratio":"64:1"}]},
    {"id":"a1000025-0000-0000-0000-000000000025","purpose":"Fast interior surface cleaning for leather, vinyl, plastic, and rubber. Delivers an instant clean, natural factory finish. Excellent for maintenance cleaning between deeper details.","instructions":"1. Dilute per the job scenario below.\n2. Spray onto surface or onto a clean microfiber towel.\n3. Wipe evenly across the surface in overlapping motions.\n4. For textured surfaces: use a soft detailing brush.\n5. Wipe clean with a dry microfiber towel for a streak-free finish.\n6. No rinsing required.","dilutions":[{"scenario":"Maintenance / Light","ratio":"3:1"},{"scenario":"Standard","ratio":"1:1"},{"scenario":"Heavy Dirt / Degreasing","ratio":"1:1"}]},
    {"id":"a1000026-0000-0000-0000-000000000026","purpose":"Versatile interior and exterior all-purpose cleaner and degreaser. Used as a pre-treatment on carpet stains, vinyl surfaces, engine bays, wheel wells, and general exterior pre-wash.","instructions":"1. Dilute per the job scenario below.\n2. Apply to the target surface via spray bottle.\n3. Allow to dwell for 1 to 3 minutes depending on soil level.\n4. Agitate with the appropriate brush.\n5. Wipe clean with a microfiber towel or rinse thoroughly.\n6. Do not allow to dry on the surface.","dilutions":[{"scenario":"Maintenance / Light","ratio":"10:1"},{"scenario":"Standard","ratio":"10:1"},{"scenario":"Heavy Dirt / Degreasing","ratio":"4:1"}]},
    {"id":"a1000027-0000-0000-0000-000000000027","purpose":"Quick paint surface maintenance between full details. Removes light dust, fingerprints, and fresh contamination without water. Enhances gloss and adds a layer of paint protection.","instructions":"1. Product is ready to use — no dilution required.\n2. Mist lightly onto one panel at a time.\n3. Gently wipe with a clean, plush microfiber towel using light pressure.\n4. Flip to a clean side of the towel and buff to a high-gloss finish.\n5. Work one panel at a time to prevent product from drying.\n6. Do not use on very dirty or heavily contaminated paint.\n7. Store in a cool location.","dilutions":[{"scenario":"Standard","ratio":"RTU"},{"scenario":"Clay Bar Lubricant","ratio":"RTU (mist lightly)"}]},
    {"id":"a1000028-0000-0000-0000-000000000028","purpose":"Glass water repellent treatment for windshields. Dramatically improves wet weather visibility by causing water to bead and roll off. Reduces wiper usage and streaking.","instructions":"1. Product is ready to use.\n2. Ensure the glass is clean.\n3. Apply a small amount to a clean, dry applicator pad or paper towel.\n4. Apply to the glass surface in overlapping circular motions.\n5. Allow product to haze and dry for 2 to 5 minutes.\n6. Buff off the haze using a clean, damp microfiber towel.\n7. Perform a final buff with a dry microfiber towel.\n8. Apply a second coat immediately for longer-lasting protection.","dilutions":[{"scenario":"Standard","ratio":"RTU"},{"scenario":"Maximum Protection","ratio":"RTU"}]},
    {"id":"a1000029-0000-0000-0000-000000000029","purpose":"Exterior pre-wash bug and road grime remover. Applied before the main wash to dissolve bug splatter, tar, bird dropping etch, and heavy road contamination.","instructions":"1. Dilute per the job scenario below.\n2. Apply to a cool vehicle before washing — do not apply in direct sunlight.\n3. Spray liberally onto bug-impacted areas.\n4. Allow to dwell for 3 to 5 minutes to dissolve contamination.\n5. Do not allow to dry on the surface.\n6. Agitate lightly with a soft brush or microfiber towel if necessary.\n7. Rinse thoroughly with water before proceeding with the main wash.","dilutions":[{"scenario":"Maintenance / Light","ratio":"10:1"},{"scenario":"Standard","ratio":"10:1"},{"scenario":"Heavy Dirt / Degreasing","ratio":"4:1"}]},
    {"id":"a1000030-0000-0000-0000-000000000030","purpose":"Quick paint protection and gloss enhancement. Applied as a drying aid on wet paint or as a spray wax on dry paint. Adds a layer of wax protection and brilliant shine.","instructions":"1. Product is ready to use.\n2. For wet application: spray onto wet paint after final rinse. Dry with towel.\n3. For dry application: mist lightly onto a clean panel and buff.\n4. Work one panel at a time.\n5. Flip towel to a dry side and perform a final buff.\n6. Can also be added to foam cannon for wash and protect step.","dilutions":[{"scenario":"Maintenance / Light","ratio":"RTU"},{"scenario":"Standard","ratio":"RTU"},{"scenario":"Heavy Dirt / Degreasing","ratio":"RTU"}]},
    {"id":"a1000031-0000-0000-0000-000000000031","purpose":"Tire and rubber dressing for a high-gloss, long-lasting wet-look shine. Conditions and protects rubber and plastic surfaces from UV damage and cracking.","instructions":"1. Ensure surface is clean and free of old dressing, dirt, and wax.\n2. Apply product to a foam tire applicator.\n3. Spread evenly across the tire sidewall in circular motions.\n4. Also apply to any rubber trim, plastic bumpers, etc.\n5. Allow to penetrate and dry for 5 to 10 minutes.\n6. Wipe off any excess from painted surfaces immediately.\n7. Allow tires to fully dry before driving to prevent sling.","dilutions":[{"scenario":"Standard","ratio":"RTU"},{"scenario":"Extended Shine","ratio":"RTU (apply second coat)"}]},
    {"id":"a1000032-0000-0000-0000-000000000032","purpose":"Premium maintenance wash that cleans and adds a layer of carnauba wax protection simultaneously. Enhances gloss and water beading with every wash.","instructions":"1. Dilute per the job scenario below.\n2. Rinse the vehicle thoroughly before washing to remove loose dirt.\n3. For bucket wash: add diluted product to bucket and generate foam.\n4. For foam cannon: dilute at 3:1 to 5:1 and apply foam.\n5. Wash from the top downward using a clean microfiber wash mitt.\n6. Rinse mitt frequently using the two-bucket method.\n7. Rinse vehicle thoroughly with clean water.\n8. Dry with a microfiber drying towel.","dilutions":[{"scenario":"Maintenance / Light","ratio":"10:1"},{"scenario":"Standard","ratio":"5:1"},{"scenario":"Foam Cannon","ratio":"3:1"}]},
    {"id":"a1000033-0000-0000-0000-000000000033","purpose":"Pre-treatment enzyme spot and stain remover for carpets and upholstery. Step 1 in the P&S Double Black System. Targets and eliminates protein-based stains, grease, oil, and odors.","instructions":"1. Vacuum and dry-brush interior carpets and upholstery before applying.\n2. Product is ready to use — do not dilute.\n3. Spray Terminator directly onto the stain or spot first.\n4. Allow product to penetrate for a minimum of 3 minutes.\n5. Agitate with a carpet brush using circular scrubbing motions.\n6. Do not over-wet the area.\n7. Proceed immediately with Step 2 — apply P&S Carpet Bomber.\n8. Extract with a wet/dry vacuum or carpet extractor.\n9. Vacuum when dry to restore fiber texture.","dilutions":[{"scenario":"Maintenance / Light","ratio":"RTU"},{"scenario":"Standard","ratio":"RTU"},{"scenario":"Heavy Dirt / Degreasing","ratio":"RTU (multiple passes)"}]},
    {"id":"a1000034-0000-0000-0000-000000000034","purpose":"All-in-one interior surface cleaning and UV protection. Cleans and protects dashboards, door panels, consoles, vinyl, leather, rubber, and plastic in a single step. Leaves natural finish.","instructions":"1. Shake well before use.\n2. Spray onto the surface or onto a clean microfiber towel.\n3. Wipe evenly across all interior surfaces using overlapping motions.\n4. For textured plastic: use a detailing brush to work product into texture.\n5. Buff with a dry clean microfiber towel for a streak-free natural finish.\n6. No rinsing required.","dilutions":[{"scenario":"Standard","ratio":"RTU"},{"scenario":"Deep Clean","ratio":"RTU (apply with brush)"}]},
    {"id":"a1000035-0000-0000-0000-000000000035","purpose":"Permanent restoration of faded and gray exterior plastic trim using ceramic coating technology. Restores faded trim to a deep black finish. Provides years of UV protection.","instructions":"1. Clean the plastic trim surface thoroughly.\n2. Use included surface prep pad (Step 2) to lightly abrade and clean.\n3. Apply the Cerakote ceramic clear coating (Step 3) using applicator pad.\n4. Work in small sections — apply sparingly.\n5. Allow coating to flash and cure on the surface per instructions.\n6. Buff lightly with a microfiber towel to even the finish.\n7. Allow to fully cure for 24 hours before washing or moisture exposure.","dilutions":[{"scenario":"Standard","ratio":"RTU (supplied in kit)"},{"scenario":"Severely Faded Trim","ratio":"RTU (apply second coat)"}]},
    {"id":"a1000036-0000-0000-0000-000000000036","purpose":"Simultaneous drying aid and paint wax protection in a single step. Applied to wet paint after rinsing to dry the vehicle and apply a layer of wax protection at the same time.","instructions":"1. Product is ready to use — no dilution required.\n2. Apply immediately after the final rinse while the vehicle is still wet.\n3. Spray liberally over wet panels — work one section at a time.\n4. Using a clean microfiber drying towel, dry the panel in straight motions.\n5. The wax formula bonds to the paint during this drying step.\n6. Flip towel to a dry side and perform a final buff.\n7. Move quickly from panel to panel before product dries in the sun.","dilutions":[{"scenario":"Standard","ratio":"RTU"},{"scenario":"Foam Cannon Additive","ratio":"RTU (add to final rinse bucket)"}]},
    {"id":"a1000037-0000-0000-0000-000000000037","purpose":"Spot treatment and stain removal for interior and exterior surfaces. Removes tar, adhesive, tree sap, grease, and stubborn stains from carpet, upholstery, paint, and vinyl.","instructions":"1. Dilute per the job scenario below — use with caution at full strength on paint.\n2. Apply directly to the stain or contamination spot.\n3. Allow to dwell for 1 to 3 minutes to dissolve contamination.\n4. Agitate with a microfiber towel or soft brush.\n5. Wipe clean with a fresh microfiber towel.\n6. For paint surfaces: rinse the area with clean water after removal.\n7. Repeat application for stubborn contamination.","dilutions":[{"scenario":"Maintenance / Light","ratio":"10:1"},{"scenario":"Standard","ratio":"5:1"},{"scenario":"Heavy Dirt / Degreasing","ratio":"1:1 (RTU for extreme spots)"}]}
  ]'::jsonb
)
WHERE key = 'ricks_chemical_tips_v3';

